/// <summary>
/// Mobile-flow label capture seams.
/// The instance CoC on <c>printDocument</c> opens a disposable capture scope; the static CoC on
/// <c>printLabelToPrinter</c> — the universal ZPL chokepoint, which fires BEFORE the
/// batch-print diversion and is reached by both the legacy routing path and the
/// new label-layout path — stages each label while a scope is active.
/// </summary>
[ExtensionOf(classStr(WhsDocumentRouting))]
public final class WhsDocumentRouting_AAXWarehouseTools_Extension
{
}

Method.Source:
public void printDocument(WHSWorkTransType _workTransType, WHSLicensePlateLabel _label)
{
    // Capture gate: WorkId must be non-empty (no attachment target otherwise) AND
    // the auto-off-guarded toggle must be on. Production LP labels
    // (ProdLicensePlateLabelBuild) and WorkId-less reprints are excluded by design.
    // CoC rule: 'next' must be called exactly once and UNCONDITIONALLY, so the scope is
    // always created and carries an active flag instead of branching around next.
    boolean capture = _label.WorkId
        && WHSParameters::find().aaxIsPreviewToWorkAttachmentEnabled();

    using (AAXWHSLabelCaptureScope scope = AAXWHSLabelCaptureScope::newFromLabel(_label, capture))
    {
        next printDocument(_workTransType, _label);
    }
}

public static void printLabelToPrinter(Name _printerName, str _label)
{
    // Universal ZPL chokepoint - fires BEFORE the batch diversion, so batching
    // cannot detach capture. No active scope (wave/TMS/production flows) => no-op.
    AAXWHSLabelCaptureScope scope = AAXWHSLabelCaptureScope::current();

    if (scope && _label)
    {
        scope.stageLabel(_printerName, _label);
    }

    next printLabelToPrinter(_printerName, _label);
}
